<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { MemoMessage } from './domain'
const props=defineProps<{messages:MemoMessage[];scopeLabel?:string;ignored:boolean;loading:boolean;busy:boolean;error:string}>()
const emit=defineEmits<{close:[];toggle:[ignored:boolean];open:[message:MemoMessage];ignore:[message:MemoMessage];restore:[message:MemoMessage]}>()
const page=ref(1),filter=ref('all')
const isReminder=(m:MemoMessage)=>['reminder','monthly_report','weekly_review'].includes(m.kind)
const visible=computed(()=>props.messages.filter(m=>!!m.ignored===props.ignored&&(filter.value==='all'||(filter.value==='reminder'?isReminder(m):!isReminder(m)))))
const pages=computed(()=>Math.max(1,Math.ceil(visible.value.length/5)))
watch([()=>props.ignored,filter],()=>{page.value=1})
watch(pages,total=>{page.value=Math.min(page.value,total)})
function label(message:MemoMessage){return({reminder:'备忘提醒',monthly_report:'月度复盘',weekly_review:'待补评价',memo_deletion_request:'备忘删除申请',plan_deletion_request:'愿望计划删除申请',expense_change_request:'财务更正申请',expense_category_change:'分类调整申请',family_invite:'家庭邀请'} as Record<string,string>)[message.kind]??'消息'}
</script>
<template>
<div class="modal-backdrop" @click.self="emit('close')" @keydown.esc.stop="emit('close')"><section class="form-card life-inbox" role="dialog" aria-modal="true" aria-label="消息提醒"><div class="form-title"><div><h2>消息提醒</h2><p class="form-note">{{ visible.length }} 条{{ ignored?'已忽略':'待处理' }} · {{ scopeLabel || '当前范围' }}</p></div><button type="button" class="icon-button" aria-label="关闭消息提醒" @click="emit('close')">×</button></div><div class="inbox-controls"><button type="button" class="text-button" :aria-pressed="ignored" :disabled="busy" @click="emit('toggle',!ignored)">{{ ignored?'返回待处理':'已忽略' }}</button><label>筛选<select v-model="filter" aria-label="筛选消息"><option value="all">全部</option><option value="request">申请与邀请</option><option value="reminder">提醒</option></select></label></div><p v-if="error" class="field-error" role="alert">{{ error }}</p><p v-if="loading" class="form-note" role="status">正在核对消息…</p><article v-for="message in visible.slice((page-1)*5,page*5)" :key="message.id" class="inbox-message"><button type="button" class="inbox-row" :disabled="busy" @click="emit('open',message)"><span><small>{{ label(message) }}</small><strong>{{ message.title }}</strong><small>{{ new Date(message.created_at).toLocaleString('zh-CN') }}</small></span><span aria-hidden="true">›</span></button><button v-if="ignored" type="button" class="text-button" :disabled="busy" :aria-label="`恢复消息：${message.title}`" @click="emit('restore',message)">恢复</button><button v-else type="button" class="text-button" :disabled="busy" :aria-label="`忽略消息：${message.title}`" @click="emit('ignore',message)">忽略</button></article><p v-if="!visible.length&&!loading" class="empty">{{ ignored?'没有已忽略的有效消息':'暂时没有待处理消息' }}</p><div v-if="pages>1" class="pagination"><button type="button" class="text-button" :disabled="page===1" @click="page--">上一页</button><span>第 {{ page }} / {{ pages }} 页</span><button type="button" class="text-button" :disabled="page===pages" @click="page++">下一页</button></div></section></div>
</template>

<style scoped>
.life-inbox{width:min(100%,520px);max-height:88dvh;overflow:auto}.inbox-controls{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:16px 0}.inbox-controls label{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--sl-muted,#63766F)}.inbox-controls select{min-height:44px;max-width:155px;border:1px solid var(--sl-line,#DCE6E1);border-radius:10px;background:white;font-size:14px;padding:8px}.inbox-message{display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--sl-line,#DCE6E1);padding:12px 0;min-width:0}.inbox-row{display:flex;align-items:center;gap:12px;border:0;background:none;flex:1;min-width:0;min-height:76px;padding:4px 0;text-align:left}.inbox-row>span:first-child{display:flex;flex-direction:column;gap:6px;min-width:0;flex:1}.inbox-row strong{font-size:15px;line-height:1.65;font-weight:550;overflow-wrap:anywhere}.inbox-row small{font-size:12px;color:var(--sl-muted,#63766F)}.inbox-row small:first-child{color:var(--sl-brand,#007F69);font-size:11px}.inbox-row>span:last-child{flex:none;color:var(--sl-muted,#63766F)}.inbox-message>.text-button{flex:none;min-width:44px;min-height:44px;font-size:13px}.pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:16px;font-size:12px}
</style>
